from pathlib import Path
import base64,zlib,runpy,shutil
p=Path(__file__).resolve().parent;r=p.parents[1]
for n in ['groups.log','group_validation.json']:
    if (p/n).exists(): shutil.copyfile(p/n,p/('fixture_correction_'+n))
(p/'check_groups.gd').write_bytes(zlib.decompress(base64.b64decode('')))
entry="\n\n## 20260915-selected-range-06 — Group renderer installed; validation checkpoint\n\nNew max-opacity group shader and retained group quad installed; individual shader remains byte-identical. Selection controller adds display-only Select All metadata. Actual native class buttons select correct members in all15 map/class combinations, and inspected Harold group preview shows the intended faint outlines under scenery. Five rendered-pixel checks pass: 12 coincident outlines exactly equal one, distinct crossing outlines equal the maximum individual mask, center/outside are transparent, visible alpha remains capped. Initial fixture clicked before active HUD layout; corrected with settle. Larger homogeneous-squad test then exposed invalid test equipment (class changed while rifle/SMG model IDs remained), correctly yielding no range; fixture corrected to valid pistols. No runtime fix needed for either test-fixture issue. Final full group rerun and existing individual234 checks running. Preserve failed logs in own group-tools folder; final authoritative report follows.\n"
for name in ['DEAD_STREET_JOURNAL.md','DEAD_STREET_HIVE_MIND.md']:
    f=r/'docs'/name;before=f.read_bytes();s=before.decode('utf-8')
    if entry.strip() not in s:
        assert f.read_bytes()==before
        f.write_text(s+entry,encoding='utf-8',newline='\n')
runpy.run_path(str(p/'run.py'),run_name='__main__')
